60	    /** Converts a telephone to its E.164 string, or throws when no valid form exists. */
61	    static String toE164(String telephone) {
62	        String trimmed = telephone == null ? "" : telephone.trim();
63	        String digits = trimmed.replaceAll("\\D", "");
64	        if (!trimmed.startsWith("+")) {
65	            if (digits.startsWith("0")) {
66	                digits = digits.substring(1);
67	            }
68	            digits = "61" + digits;
69	        }
70	        if (digits.length() < 8 || digits.length() > 15) {
71	            throw new InvalidTelephoneException();
72	        }
73	        return "+" + digits;
74	    }
