36	/**
37	 * Normalizes an owner's email before the request reaches the controller: when present it
38	 * is lower-cased and must be a syntactically valid address or the request is rejected
39	 * with a 400. An absent email is left untouched and accepted. Kept as its own advice so
40	 * this rule stays a small, self-contained unit rather than growing the controller or
41	 * another handler.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerEmailNormalizationAdvice extends RequestBodyAdviceAdapter {
46	
47	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
48	
49	    @Override
50	    public boolean supports(MethodParameter methodParameter, Type targetType,
51	                            Class<? extends HttpMessageConverter<?>> converterType) {
52	        return OwnerFieldsDto.class.equals(targetType);
53	    }
54	
55	    @Override
56	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
57	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
58	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
59	        owner.setEmail(normalize(owner.getEmail()));
60	        return body;
61	    }
62	
63	    private String normalize(String email) {
64	        if (email == null || email.isBlank()) {
65	            return email;
66	        }
67	        String normalized = email.strip().toLowerCase(Locale.ROOT);
68	        if (!EMAIL.matcher(normalized).matches()) {
69	            throw new InvalidEmailException();
70	        }
71	        return normalized;
72	    }
73	
74	    @ExceptionHandler(InvalidEmailException.class)
75	    @ResponseBody
76	    public ResponseEntity<String> handleInvalidEmail(InvalidEmailException e) {
77	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
78	    }
79	
80	    /** Signals an email that is present but not a syntactically valid address. */
81	    static class InvalidEmailException extends RuntimeException {
82	
83	        InvalidEmailException() {
84	            super("email must be a valid address");
85	        }
86	    }
87	}
